"""Read-only inspection of actually persisted pixel evidence; no fixtures or hidden actor data."""
import sqlite3,json,argparse,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];p=argparse.ArgumentParser();p.add_argument('--run',default='p2-09-vision');p.add_argument('--output',type=Path,required=True);a=p.parse_args();db=sqlite3.connect('file:'+str(ROOT/'simulation/spatial-office/.runtime/p2-core.sqlite3')+'?mode=ro',uri=True);db.row_factory=sqlite3.Row;site='coworking-p2';items={r['entity']:json.loads(r['body'])for r in db.execute("SELECT entity,body FROM office_state WHERE site=? AND run=? AND branch='main'",(site,a.run))};tracks=[e for e in items.values()if e['kind']=='Track'];cams=[e for e in items.values()if e['kind']=='Camera'];links=[{'source':t['id'],**r}for t in tracks for r in t.get('relations',[])if r['type']=='provisionallySameVisualSubject'and not r.get('valid_to')];events=dict(db.execute('SELECT type,COUNT(*) FROM office_events WHERE site=? AND run=? GROUP BY type',(site,a.run)).fetchall());memory={e['id']:db.execute('SELECT COUNT(*) FROM memories WHERE entity_id=?',(e['core_id'],)).fetchone()[0]for e in tracks+cams+[items['site']]};inbox=[json.loads(r[0])for r in db.execute('SELECT body FROM office_inbox WHERE site=? AND run=?',(site,a.run))];assert len(tracks)==8 and len(links)==5;assert len(inbox)==251;assert len([e for e in items.values()if e['kind']=='Person'])==14;assert all(not t.get('person_id')for t in tracks);assert all(memory[t['id']]>0 for t in tracks);assert all(memory[c['id']]>0 for c in cams if c.get('last_frame_sha256'));assert all(not r.get('presence')for r in items.values()if r['kind']=='Person');assert all(m['type']in ['edge.presence','edge.track_association']for m in inbox)
report={'gate':'P2-09.8','read_only':True,'passed':True,'run':a.run,'entities_total':len(items),'observations_persisted':len(inbox),'anonymous_tracks':tracks,'camera_sources':[{k:e.get(k)for k in ['id','core_id','model_status','integration_status','verification_scope','last_frame_sha256','frame_index','media_time_seconds','connectivity','spatial','live_stream_implemented']}for e in cams],'provisional_relations':links,'events_by_type':events,'memory_records':memory,'new_person_identities':0,'civil_identity_verified':False,'no_occupancy_or_business_facts_inferred':True};a.output.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:v for k,v in report.items()if k in ['entities_total','observations_persisted','new_person_identities','events_by_type','memory_records']}))
